(()=>{let trash=false,loading=false;function decorate(){if(tab!==5)return;const box=document.querySelector('#filmExportHistory');if(!box)return;if(!document.querySelector('#filmTrashToggle')){const bar=document.createElement('div');bar.style.cssText='display:flex;gap:12px;align-items:center;margin:16px 0';bar.innerHTML='<b>成片记录</b><button id="filmTrashToggle">'+(trash?'返回成片记录':'成片回收站')+'</button>';box.before(bar);bar.querySelector('button').onclick=async()=>{trash=!trash;bar.querySelector('button').textContent=trash?'返回成片记录':'成片回收站';filmExports=[];await loadFilmExports();};}for(const card of box.querySelectorAll('[data-film-id]')){if(card.querySelector('[data-film-remove]'))continue;const j=filmExports.find(x=>x.id===card.dataset.filmId);if(!j)continue;const button=document.createElement('button');button.dataset.filmRemove=j.id;button.textContent=j.deleted?'恢复成片':'删除成片';button.disabled=['queued','running'].includes(j.status);button.style.marginTop='8px';button.onclick=async()=>{button.disabled=true;try{await frontFetch('/api/film-export/'+j.id+(j.deleted?'/restore':'/delete'),{});filmExports=filmExports.filter(x=>x.id!==j.id);drawFilmExports();toast(j.deleted?'成片已恢复':'成片已移入回收站');}catch(e){toast(e.message);button.disabled=false;}};card.append(button);}}
const oldFetch=frontFetch;frontFetch=async function(url,body){if(!body&&url.startsWith('/api/film-export?')&&trash)url+='&trash=1';return oldFetch(url,body);};const oldDraw=drawFilmExports;drawFilmExports=function(){oldDraw();decorate();};const oldStage=stage;stage=function(){oldStage();if(tab===5)decorate();};render();})();
